# report-envelope.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/report-envelope.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "status": {
            "const": "waiting_human"
          }
        }
      },
      "then": {
        "required": [
          "waiting_for_human"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "status": {
            "const": "done"
          }
        }
      },
      "then": {
        "properties": {
          "waiting_for_human": {
            "type": "null"
          }
        }
      }
    }
  ],
  "description": "Immutable correlation, assignment, timing, and verification metadata. Requester-selected content is carried separately.",
  "properties": {
    "assignment": {
      "additionalProperties": false,
      "properties": {
        "assignment_id": {
          "minLength": 1,
          "type": "string"
        },
        "completion_policy": {
          "minLength": 1,
          "type": "string"
        },
        "criteria_refs": {
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "minItems": 1,
          "type": "array"
        },
        "required_content": {
          "enum": [
            "free_form",
            "structured",
            "dataset"
          ]
        },
        "schema_ref": {
          "additionalProperties": false,
          "properties": {
            "digest": {
              "pattern": "^sha256:[A-Fa-f0-9]{64}$",
              "type": "string"
            },
            "name": {
              "minLength": 1,
              "type": "string"
            },
            "version": {
              "minLength": 1,
              "type": "string"
            }
          },
          "required": [
            "name",
            "version",
            "digest"
          ],
          "type": [
            "object",
            "null"
          ]
        },
        "validation_policy": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "assignment_id",
        "required_content",
        "validation_policy",
        "completion_policy",
        "criteria_refs"
      ],
      "type": "object"
    },
    "attempt": {
      "minimum": 1,
      "type": "integer"
    },
    "attempt_id": {
      "minLength": 1,
      "type": "string"
    },
    "commit_seq": {
      "minimum": 1,
      "type": "integer"
    },
    "content_class": {
      "enum": [
        "free_form",
        "structured",
        "dataset"
      ]
    },
    "content_digest": {
      "pattern": "^sha256:[A-Fa-f0-9]{64}$",
      "type": "string"
    },
    "content_ref": {
      "minLength": 1,
      "type": "string"
    },
    "criteria_results": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "criterion_id": {
            "minLength": 1,
            "type": "string"
          },
          "evidence_refs": {
            "items": {
              "minLength": 1,
              "type": "string"
            },
            "minItems": 1,
            "type": "array"
          },
          "note": {
            "type": "string"
          },
          "verdict": {
            "enum": [
              "pass",
              "fail",
              "not_run",
              "waived"
            ]
          }
        },
        "required": [
          "criterion_id",
          "verdict",
          "evidence_refs"
        ],
        "type": "object"
      },
      "minItems": 1,
      "type": "array"
    },
    "dispatch_ts": {
      "format": "date-time",
      "type": "string"
    },
    "evidence_refs": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "minItems": 1,
      "type": "array"
    },
    "ingest_ts": {
      "format": "date-time",
      "type": "string"
    },
    "late_report": {
      "type": "boolean"
    },
    "parent_thread_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "record_id": {
      "minLength": 1,
      "type": "string"
    },
    "report_id": {
      "minLength": 1,
      "type": "string"
    },
    "request_ref": {
      "pattern": "^/chd/room/[^/]+/m[0-9]{12}$",
      "type": "string"
    },
    "rev": {
      "minimum": 1,
      "type": "integer"
    },
    "room": {
      "minLength": 1,
      "type": "string"
    },
    "schema_version": {
      "const": 3
    },
    "send_id": {
      "minLength": 1,
      "type": "string"
    },
    "session_ref": {
      "additionalProperties": false,
      "properties": {
        "generation": {
