        "session_key"
      ],
      "type": "object"
    },
    "status": {
      "enum": [
        "done",
        "deferred",
        "blocked",
        "failed",
        "waiting_human"
      ]
    },
    "waiting_for_human": {
      "additionalProperties": false,
      "properties": {
        "asked_at": {
          "format": "date-time",
          "type": "string"
        },
        "gate_ref": {
          "minLength": 1,
          "type": "string"
        },
        "question": {
          "minLength": 1,
          "type": "string"
        },
        "requested_by": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "question",
        "gate_ref",
        "asked_at",
        "requested_by"
      ],
      "type": [
        "object",
        "null"
      ]
    },
    "written_by": {
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "record_id",
    "rev",
    "commit_seq",
    "written_by",
    "report_id",
    "send_id",
    "attempt_id",
    "attempt",
    "request_ref",
    "room",
    "session_ref",
    "status",
    "content_class",
    "content_ref",
    "content_digest",
    "dispatch_ts",
    "ingest_ts",
    "assignment",
    "criteria_results",
    "evidence_refs"
  ],
  "title": "CHD Report Correlation Envelope v3",
  "type": "object"
